export interface WorkspaceLink {
  label: string;
  route: string;
}

export interface WorkspaceFrameOptions {
  logoText: string;
  links: readonly WorkspaceLink[];
  activeRoute: string;
  content: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/\"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

export function renderWorkspaceFrame(options: WorkspaceFrameOptions): string {
  if (typeof options !== "object" || options === null ||
      typeof options.logoText !== "string" || typeof options.activeRoute !== "string" ||
      typeof options.content !== "string" || !Array.isArray(options.links)) {
    throw new TypeError("malformed options");
  }
  const anchors = options.links.map((link) => {
    if (typeof link !== "object" || link === null || typeof link.label !== "string" ||
        typeof link.route !== "string" || link.route.trim() === "" || !link.route.startsWith("/")) {
      throw new TypeError("malformed link");
    }
    const current = link.route === options.activeRoute ? ' aria-current="page"' : "";
    return `<a class="workspace-link" href="${escapeHtml(link.route)}"${current}>${link.label}</a>`;
  }).join("");
  return `<div class="workspace"><header class="workspace-header"><span class="workspace-logo">${escapeHtml(options.logoText)}</span><nav class="workspace-nav">${anchors}</nav></header><main class="workspace-main">${escapeHtml(options.content)}</main></div>`;
}
```

