import { renderWorkspaceFrame } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const links = [
  { label: 'A&B <Home>', route: '/home?x=1&y="two"' },
  { label: 'Other \'page\'', route: '/other' },
];
const html = renderWorkspaceFrame({
  logoText: '<Forge & "Co">',
  links,
  activeRoute: '/home?x=1&y="two"',
  content: 'Content: <tag a="b"> & \'quoted\'',
});
assert(html === '<div class="workspace"><header class="workspace-header"><span class="workspace-logo">&lt;Forge &amp; &quot;Co&quot;&gt;</span><nav class="workspace-nav"><a class="workspace-link" href="/home?x=1&amp;y=&quot;two&quot;" aria-current="page">A&amp;B &lt;Home&gt;</a><a class="workspace-link" href="/other">Other &#39;page&#39;</a></nav></header><main class="workspace-main">Content: &lt;tag a=&quot;b&quot;&gt; &amp; &#39;quoted&#39;</main></div>', 'exact structure, escaping, order, and active link');
assert(links[0].label === 'A&B <Home>' && links.length === 2, 'input not mutated');

const empty = renderWorkspaceFrame({ logoText: '', links: [], activeRoute: '/', content: '' });
assert(empty === '<div class="workspace"><header class="workspace-header"><span class="workspace-logo"></span><nav class="workspace-nav"></nav></header><main class="workspace-main"></main></div>', 'empty navigation');

throwsTypeError(() => renderWorkspaceFrame(null as any), 'options object required');
throwsTypeError(() => renderWorkspaceFrame({ logoText: 2, links: [], activeRoute: '/', content: '' } as any), 'logo type');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: null, activeRoute: '/', content: '' } as any), 'links array required');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: [], activeRoute: ' ', content: '' } as any), 'blank active route');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: [], activeRoute: 'relative', content: '' } as any), 'active route prefix');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: [{ label: 1, route: '/x' }], activeRoute: '/', content: '' } as any), 'link label type');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: [{ label: 'x', route: 'relative' }], activeRoute: '/', content: '' }), 'link route prefix');
throwsTypeError(() => renderWorkspaceFrame({ logoText: '', links: [{ label: 'x', route: '   ' }], activeRoute: '/', content: '' }), 'blank link route');

